-- Phase 20 scaffold; review/test before production.
create table if not exists public.blueprints(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,assessment_id uuid references public.assessments(id),template_version text not null,status text not null default 'draft',storage_path text,qa_by uuid,qa_at timestamptz,created_at timestamptz not null default now());
alter table public.blueprints enable row level security; revoke all on public.blueprints from anon,authenticated; grant select on public.blueprints to authenticated;
create policy blueprints_select_own on public.blueprints for select to authenticated using(exists(select 1 from public.customers c where c.id=customer_id and c.user_id=auth.uid()) and status='approved');
create table if not exists public.opportunity_briefs(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,blueprint_id uuid references public.blueprints(id) on delete cascade,possibility_key text not null,status text not null default 'draft',research_as_of date,content jsonb not null default '{}'::jsonb,source_metadata jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
alter table public.opportunity_briefs enable row level security; revoke all on public.opportunity_briefs from anon,authenticated; grant select on public.opportunity_briefs to authenticated;
create policy briefs_select_own on public.opportunity_briefs for select to authenticated using(exists(select 1 from public.customers c where c.id=customer_id and c.user_id=auth.uid()) and status='approved');
